const fs = require("fs");

const POLICY = JSON.parse(fs.readFileSync(path.join(__dirname, "rules", "net-policy.json"), "utf8"));
const MANIFEST_FILE = "nx-capabilities.yml";
const STAMP_FILE = "nx-capabilities.properties";

const DENIED = [];
for (const [reason, list] of Object.entries(POLICY.deniedSuffixes)) for (const s of list) DENIED.push([s, reason]);

const LABEL = /^(?!-)[a-z0-9-]{1,63}(?<!-)$/;
const IPV4ISH = /^[0-9.]+$/;

/** Why a hostname may not be declared, or null when it may. */
function hostProblem(h) {
  if (typeof h !== "string" || !h) return "is empty";
  if (h !== h.trim() || /\s/.test(h)) return "contains spaces";
  if (/[A-Z]/.test(h)) return "must be lower case";
  if (h.includes("*")) return "must be one exact name (no wildcards)";
  if (h.includes(":") || h.includes("[")) return "must be a name without a port or IP address";
  if (h.includes("/") || h.includes("@")) return "must be a bare hostname (no scheme, path or user)";
  if (h.endsWith(".")) return "must not end with a dot";
  if (h.length > 253) return "is too long";
  if (IPV4ISH.test(h) || /^0x/i.test(h)) return "is an IP address (declare a hostname)";
  const labels = h.split(".");
  if (labels.length < 2) return "needs a domain (for example api.example.com)";
  if (!labels.every((l) => LABEL.test(l))) return "is not a valid hostname";
  if (!/^[a-z]{2,63}$|^xn--[a-z0-9-]{1,59}$/.test(labels[labels.length - 1])) return "has no valid top-level domain";
  for (const [suffix, reason] of DENIED) if (h === suffix || h.endsWith("." + suffix)) return `is not allowed (${reason})`;
  return null;
}

function cleanText(x, max) {
  return String(x == null ? "" : x).replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
}

/** raw: the parsed YAML object (or null). Returns { ok, problems: string[], manifest|null }. */
function validateManifest(raw) {
  const problems = [];
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, problems: [`${MANIFEST_FILE} must be a YAML mapping.`], manifest: null };
  const known = new Set(["version", "network", "secrets", "ai"]);
  for (const k of Object.keys(raw)) if (!known.has(k)) problems.push(`${MANIFEST_FILE}: unknown key "${k}" (allowed: version, network, secrets, ai).`);
  if (raw.version !== 1 && raw.version !== "1") problems.push(`${MANIFEST_FILE}: version must be 1.`);
  const net = raw.network == null ? null : raw.network;
  const hosts = [];
  let playerData = [];
  let maxResponseKiB = POLICY.responseKiB.default;
  if (net != null) {
    if (typeof net !== "object" || Array.isArray(net)) problems.push(`${MANIFEST_FILE}: network must be a mapping.`);
    else {
      for (const k of Object.keys(net)) if (!["hosts", "playerData", "maxResponseKiB"].includes(k)) problems.push(`${MANIFEST_FILE}: unknown key network.${k}.`);
      const list = Array.isArray(net.hosts) ? net.hosts : [];
      if (!list.length) problems.push(`${MANIFEST_FILE}: network.hosts must list at least one host.`);
      if (list.length > POLICY.maxHosts) problems.push(`${MANIFEST_FILE}: at most ${POLICY.maxHosts} hosts.`);
      const seen = new Set();
      for (const e of list.slice(0, POLICY.maxHosts)) {
        const host = e && typeof e === "object" ? e.host : e;
        const why = hostProblem(host);
        if (why) { problems.push(`${MANIFEST_FILE}: host "${cleanText(host, 80)}" ${why}.`); continue; }
        if (seen.has(host)) { problems.push(`${MANIFEST_FILE}: host ${host} is listed twice.`); continue; }
        seen.add(host);
        const purpose = cleanText(e && e.purpose, POLICY.purposeMax + 1);
        if (purpose.length < POLICY.purposeMin) problems.push(`${MANIFEST_FILE}: host ${host} needs a purpose (${POLICY.purposeMin}-${POLICY.purposeMax} characters, what the mod uses it for).`);
        else if (purpose.length > POLICY.purposeMax) problems.push(`${MANIFEST_FILE}: the purpose for ${host} is longer than ${POLICY.purposeMax} characters.`);
        hosts.push({ host, purpose: purpose.slice(0, POLICY.purposeMax) });
      }
      const pd = net.playerData;
      if (pd == null || pd === "none" || (Array.isArray(pd) && !pd.length)) playerData = [];
      else if (Array.isArray(pd)) {
        for (const c of pd) if (!POLICY.playerData.includes(c)) problems.push(`${MANIFEST_FILE}: playerData "${cleanText(c, 30)}" is unknown (use ${POLICY.playerData.join(", ")} or none).`);
        playerData = POLICY.playerData.filter((c) => pd.includes(c));
      } else problems.push(`${MANIFEST_FILE}: playerData must be a list (${POLICY.playerData.join(", ")}) or none.`);
      if (net.maxResponseKiB != null) {
        const n = Number(net.maxResponseKiB);
        if (!Number.isInteger(n) || n < POLICY.responseKiB.min || n > POLICY.responseKiB.max) problems.push(`${MANIFEST_FILE}: maxResponseKiB must be a whole number from ${POLICY.responseKiB.min} to ${POLICY.responseKiB.max}.`);
        else maxResponseKiB = n;
      }
    }
  }
  const secrets = [];
  if (raw.secrets != null) {
    if (!Array.isArray(raw.secrets)) problems.push(`${MANIFEST_FILE}: secrets must be a list.`);
    else {
      if (raw.secrets.length > POLICY.maxSecrets) problems.push(`${MANIFEST_FILE}: at most ${POLICY.maxSecrets} secrets.`);
      const names = new Set();
      for (const s of raw.secrets.slice(0, POLICY.maxSecrets)) {
        if (!s || typeof s !== "object") { problems.push(`${MANIFEST_FILE}: each secret must be a mapping.`); continue; }
        const name = String(s.name || "");
        if (!/^[a-z][a-z0-9_]{1,31}$/.test(name)) { problems.push(`${MANIFEST_FILE}: secret name "${cleanText(name, 40)}" must be 2-32 lower-case letters, digits or _.`); continue; }
        if (names.has(name)) { problems.push(`${MANIFEST_FILE}: secret ${name} is listed twice.`); continue; }
        names.add(name);
        if (!hosts.some((h) => h.host === s.host)) problems.push(`${MANIFEST_FILE}: secret ${name} must be bound to one of the declared hosts.`);
        const isUrl = s.url === true;
        const header = s.header == null ? null : String(s.header);
        if (isUrl === (header != null)) problems.push(`${MANIFEST_FILE}: secret ${name} needs exactly one of header (${POLICY.secretHeaders.join(", ")}) or url: true.`);
        else if (header != null && !POLICY.secretHeaders.includes(header)) problems.push(`${MANIFEST_FILE}: secret ${name} header must be one of ${POLICY.secretHeaders.join(", ")}.`);
        secrets.push({ name, host: String(s.host || ""), ...(isUrl ? { url: true } : { header }), description: cleanText(s.description, 160) });
      }
    }
  }
  const ai = raw.ai === true;
  if (raw.ai != null && typeof raw.ai !== "boolean") problems.push(`${MANIFEST_FILE}: ai must be true or false.`);
  if (!hosts.length && !ai && !problems.length) problems.push(`${MANIFEST_FILE}: declares nothing (remove the file if the mod needs no network).`);
  if (problems.length) return { ok: false, problems: [...new Set(problems)], manifest: null };
  const manifest = { version: 1, network: hosts.length ? { hosts, playerData, maxResponseKiB } : null, secrets, ai, policy: POLICY.version };
  return { ok: true, problems: [], manifest: { ...manifest, sha256: manifestHash(manifest) } };
}

/** Stable hash of the normalized manifest (without its own sha256). Consent is bound to it. */
function manifestHash(m) {
  const { sha256, ...rest } = m; void sha256;
  return crypto.createHash("sha256").update(canonical(rest)).digest("hex");
}
function canonical(x) {
  if (Array.isArray(x)) return `[${x.map(canonical).join(",")}]`;
  if (x && typeof x === "object") return `{${Object.keys(x).sort().map((k) => `${JSON.stringify(k)}:${canonical(x[k])}`).join(",")}}`;
  return JSON.stringify(x === undefined ? null : x);
}

/**
 * The runtime stamp the service writes into the jar for the wrapper (java.util.Properties, so
 * the wrapper needs no YAML parser). The plugin's own copy of nx-capabilities.yml is kept for
 * people to read; the wrapper only trusts this file.
 */
function stampProperties(m, { buildId, pluginName, pluginVersion, blockCidrs = [], statusUrl = "", gatewayUrl = "" }) {
  const esc = (v) => String(v).replace(/\\/g, "\\\\").replace(/\n/g, "\\n").replace(/[=:#!]/g, (c) => "\\" + c);
  const lines = [
    "# Written by the Nxeon build service. Do not edit: the wrapper refuses a stamp whose hash does not match.",
    `manifest.sha256=${m.sha256}`,
    `build.id=${esc(buildId)}`,
    `plugin.name=${esc(pluginName)}`,
    `plugin.version=${esc(pluginVersion)}`,
    `hosts=${(m.network ? m.network.hosts.map((h) => h.host) : []).join(",")}`,
    `playerData=${(m.network ? m.network.playerData : []).join(",")}`,
    `maxResponseKiB=${m.network ? m.network.maxResponseKiB : POLICY.responseKiB.default}`,
    `ai=${m.ai ? "true" : "false"}`,
    `block.cidrs=${blockCidrs.join(",")}`,
    `status.url=${esc(statusUrl)}`,
    `gateway.url=${esc(m.ai ? gatewayUrl : "")}`,
  ];
  for (const s of m.secrets) lines.push(`secret.${s.name}=${s.host}|${s.url ? "url" : "header:" + s.header}`);
  const body = lines.join("\n") + "\n";
  return `${body}stamp.sha256=${crypto.createHash("sha256").update(body).digest("hex")}\n`;
}

/** Plain-language summary for consent screens (the portal has the same function in TS). */
function summarize(m) {
  if (!m) return { connects: false, lines: ["This mod does not connect to the internet."], risk: "none" };
  const lines = [];
  for (const h of (m.network ? m.network.hosts : [])) lines.push(`Connects to ${h.host}: ${h.purpose}`);
  if (m.ai) lines.push("Uses Nxeon AI (metered in your Cyrus tokens)");
  const pd = m.network ? m.network.playerData : [];
  lines.push(pd.length ? `Can send player data: ${pd.map((c) => ({ names: "player names and IDs", chat: "chat messages", ip: "IP addresses" })[c]).join(", ")}` : "Cannot send player data");
  for (const s of m.secrets) lines.push(`Asks you for a secret (${s.name}) that is only sent to ${s.host}`);
  const risk = pd.includes("ip") ? "high" : pd.length || m.secrets.length ? "medium" : "low";
  return { connects: true, lines, risk };
}

module.exports = { POLICY, MANIFEST_FILE, STAMP_FILE, hostProblem, validateManifest, manifestHash, canonical, stampProperties, summarize };

