// Cyrus mod capabilities (networking + AI): types, validation, consent summary and the
// install gate. Pure and client-safe.
//
// A mod may only use the network through the Nxeon wrapper, with every host declared in the
// mod's `nx-capabilities.yml`. The build service validates the manifest with the same rules
// (services/modbuilder/capabilities.js); both read services/modbuilder/rules/net-policy.json,
// and test/cyrus-capabilities.test.ts checks the two implementations agree.
// Design: /root/agent-notes/cyrus-v6/capabilities/DESIGN.md. Default OFF
// (setting `cyrus_mod_networking_enabled`).
import POLICY from "../../services/modbuilder/rules/net-policy.json";

export const NET_POLICY_VERSION: string = POLICY.version;
export const MANIFEST_FILE = "nx-capabilities.yml";

export type PlayerDataCategory = "names" | "chat" | "ip";
export const PLAYER_DATA_CATEGORIES = POLICY.playerData as PlayerDataCategory[];
export const PLAYER_DATA_LABEL: Record<PlayerDataCategory, string> = {
  names: "player names and IDs",
  chat: "chat messages",
  ip: "IP addresses",
};

export type CapabilityHost = { host: string; purpose: string };
export type CapabilitySecret = { name: string; host: string; header?: string; url?: true; description: string };
export type CyrusCapabilities = {
  version: 1;
  network: { hosts: CapabilityHost[]; playerData: PlayerDataCategory[]; maxResponseKiB: number } | null;
  secrets: CapabilitySecret[];
  /** May call the Nxeon AI gateway (metered in the server owner's Cyrus tokens, off until they enable it). */
  ai: boolean;
  policy: string;
  sha256: string;
};

export type ValidationResult = { ok: true; problems: []; manifest: CyrusCapabilities } | { ok: false; problems: string[]; manifest: null };

const DENIED: [string, string][] = [];
for (const [reason, list] of Object.entries(POLICY.deniedSuffixes as Record<string, string[]>)) for (const s of list) DENIED.push([s, reason]);
const LABEL = /^(?!-)[a-z0-9-]{1,63}(?<!-)$/;

/** Why a hostname may not be declared, or null when it may (same wording as the service). */
export function hostProblem(h: unknown): string | null {
  if (typeof h !== "string" || !h) return "is empty";
  if (h !== h.trim() || /\s/.test(h)) return "contains spaces";
  if (/[A-Z]/.test(h)) return "must be lower case";
  if (h.includes("*")) return "must be one exact name (no wildcards)";
  if (h.includes(":") || h.includes("[")) return "must be a name without a port or IP address";
  if (h.includes("/") || h.includes("@")) return "must be a bare hostname (no scheme, path or user)";
  if (h.endsWith(".")) return "must not end with a dot";
  if (h.length > 253) return "is too long";
  if (/^[0-9.]+$/.test(h) || /^0x/i.test(h)) return "is an IP address (declare a hostname)";
  const labels = h.split(".");
  if (labels.length < 2) return "needs a domain (for example api.example.com)";
  if (!labels.every((l) => LABEL.test(l))) return "is not a valid hostname";
  if (!/^[a-z]{2,63}$|^xn--[a-z0-9-]{1,59}$/.test(labels[labels.length - 1])) return "has no valid top-level domain";
  for (const [suffix, reason] of DENIED) if (h === suffix || h.endsWith("." + suffix)) return `is not allowed (${reason})`;
  return null;
}

function cleanText(x: unknown, max: number): string {
  return String(x == null ? "" : x).replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
}

type Raw = Record<string, unknown>;
const isObj = (x: unknown): x is Raw => !!x && typeof x === "object" && !Array.isArray(x);

/** Validate a parsed manifest (YAML mapping, or the service's normalized JSON). */
export function validateCapabilities(raw: unknown): ValidationResult {
  const F = MANIFEST_FILE;
  const problems: string[] = [];
  if (!isObj(raw)) return { ok: false, problems: [`${F} must be a YAML mapping.`], manifest: null };
  // `policy` and `sha256` are accepted (and recomputed) so normalized manifests re-validate.
  const known = new Set(["version", "network", "secrets", "ai", "policy", "sha256"]);
  for (const k of Object.keys(raw)) if (!known.has(k)) problems.push(`${F}: unknown key "${k}" (allowed: version, network, secrets, ai).`);
  if (raw.version !== 1 && raw.version !== "1") problems.push(`${F}: version must be 1.`);
  const hosts: CapabilityHost[] = [];
  let playerData: PlayerDataCategory[] = [];
  let maxResponseKiB: number = POLICY.responseKiB.default;
  const net = raw.network;
  if (net != null) {
    if (!isObj(net)) problems.push(`${F}: network must be a mapping.`);
    else {
      for (const k of Object.keys(net)) if (!["hosts", "playerData", "maxResponseKiB"].includes(k)) problems.push(`${F}: unknown key network.${k}.`);
      const list = Array.isArray(net.hosts) ? (net.hosts as unknown[]) : [];
      if (!list.length) problems.push(`${F}: network.hosts must list at least one host.`);
      if (list.length > POLICY.maxHosts) problems.push(`${F}: at most ${POLICY.maxHosts} hosts.`);
      const seen = new Set<string>();
      for (const e of list.slice(0, POLICY.maxHosts)) {
        const host = isObj(e) ? e.host : e;
        const why = hostProblem(host);
        if (why) { problems.push(`${F}: host "${cleanText(host, 80)}" ${why}.`); continue; }
        const h = host as string;
        if (seen.has(h)) { problems.push(`${F}: host ${h} is listed twice.`); continue; }
        seen.add(h);
        const purpose = cleanText(isObj(e) ? e.purpose : "", POLICY.purposeMax + 1);
        if (purpose.length < POLICY.purposeMin) problems.push(`${F}: host ${h} needs a purpose (${POLICY.purposeMin}-${POLICY.purposeMax} characters, what the mod uses it for).`);
        else if (purpose.length > POLICY.purposeMax) problems.push(`${F}: the purpose for ${h} is longer than ${POLICY.purposeMax} characters.`);
        hosts.push({ host: h, purpose: purpose.slice(0, POLICY.purposeMax) });
      }
      const pd = net.playerData;
      if (pd == null || pd === "none" || (Array.isArray(pd) && !pd.length)) playerData = [];
      else if (Array.isArray(pd)) {
        for (const c of pd) if (!PLAYER_DATA_CATEGORIES.includes(c as PlayerDataCategory)) problems.push(`${F}: playerData "${cleanText(c, 30)}" is unknown (use ${PLAYER_DATA_CATEGORIES.join(", ")} or none).`);
        playerData = PLAYER_DATA_CATEGORIES.filter((c) => (pd as unknown[]).includes(c));
      } else problems.push(`${F}: playerData must be a list (${PLAYER_DATA_CATEGORIES.join(", ")}) or none.`);
      if (net.maxResponseKiB != null) {
        const n = Number(net.maxResponseKiB);
        if (!Number.isInteger(n) || n < POLICY.responseKiB.min || n > POLICY.responseKiB.max) problems.push(`${F}: maxResponseKiB must be a whole number from ${POLICY.responseKiB.min} to ${POLICY.responseKiB.max}.`);
        else maxResponseKiB = n;
      }
    }
  }
  const secrets: CapabilitySecret[] = [];
  if (raw.secrets != null) {
    if (!Array.isArray(raw.secrets)) problems.push(`${F}: secrets must be a list.`);
    else {
      if (raw.secrets.length > POLICY.maxSecrets) problems.push(`${F}: at most ${POLICY.maxSecrets} secrets.`);
      const names = new Set<string>();
      for (const s of raw.secrets.slice(0, POLICY.maxSecrets) as unknown[]) {
        if (!isObj(s)) { problems.push(`${F}: each secret must be a mapping.`); continue; }
        const name = String(s.name || "");
        if (!/^[a-z][a-z0-9_]{1,31}$/.test(name)) { problems.push(`${F}: secret name "${cleanText(name, 40)}" must be 2-32 lower-case letters, digits or _.`); continue; }
