type Raw = Record<string, unknown>;
const isObj = (x: unknown): x is Raw => !!x && typeof x === "object" && !Array.isArray(x);

/** Validate a parsed manifest (YAML mapping, or the service's normalized JSON). */
export function validateCapabilities(raw: unknown): ValidationResult {
  const F = MANIFEST_FILE;
