      const list = Array.isArray(net.hosts) ? (net.hosts as unknown[]) : [];
      if (!list.length) problems.push(`${F}: network.hosts must list at least one host.`);
      if (list.length > POLICY.maxHosts) problems.push(`${F}: at most ${POLICY.maxHosts} hosts.`);
      const seen = new Set<string>();
      for (const e of list.slice(0, POLICY.maxHosts)) {
        const host = isObj(e) ? e.host : e;
        const why = hostProblem(host);
        if (why) { problems.push(`${F}: host "${cleanText(host, 80)}" ${why}.`); continue; }
        const h = host as string;
        if (seen.has(h)) { problems.push(`${F}: host ${h} is listed twice.`); continue; }
        seen.add(h);
        const purpose = cleanText(isObj(e) ? e.purpose : "", POLICY.purposeMax + 1);
        if (purpose.length < POLICY.purposeMin) problems.push(`${F}: host ${h} needs a purpose (${POLICY.purposeMin}-${POLICY.purposeMax} characters, what the mod uses it for).`);
