        for (const c of pd) if (!PLAYER_DATA_CATEGORIES.includes(c as PlayerDataCategory)) problems.push(`${F}: playerData "${cleanText(c, 30)}" is unknown (use ${PLAYER_DATA_CATEGORIES.join(", ")} or none).`);
        playerData = PLAYER_DATA_CATEGORIES.filter((c) => (pd as unknown[]).includes(c));
      } else problems.push(`${F}: playerData must be a list (${PLAYER_DATA_CATEGORIES.join(", ")}) or none.`);
      if (net.maxResponseKiB != null) {
        const n = Number(net.maxResponseKiB);
        if (!Number.isInteger(n) || n < POLICY.responseKiB.min || n > POLICY.responseKiB.max) problems.push(`${F}: maxResponseKiB must be a whole number from ${POLICY.responseKiB.min} to ${POLICY.responseKiB.max}.`);
        else maxResponseKiB = n;
      }
    }
  }
  const secrets: CapabilitySecret[] = [];
  if (raw.secrets != null) {
    if (!Array.isArray(raw.secrets)) problems.push(`${F}: secrets must be a list.`);
    else {
      if (raw.secrets.length > POLICY.maxSecrets) problems.push(`${F}: at most ${POLICY.maxSecrets} secrets.`);
      const names = new Set<string>();
      for (const s of raw.secrets.slice(0, POLICY.maxSecrets) as unknown[]) {
        if (!isObj(s)) { problems.push(`${F}: each secret must be a mapping.`); continue; }
        const name = String(s.name || "");
        if (!/^[a-z][a-z0-9_]{1,31}$/.test(name)) { problems.push(`${F}: secret name "${cleanText(name, 40)}" must be 2-32 lower-case letters, digits or _.`); continue; }
        if (names.has(name)) { problems.push(`${F}: secret ${name} is listed twice.`); continue; }
        names.add(name);
        if (!hosts.some((h) => h.host === s.host)) problems.push(`${F}: secret ${name} must be bound to one of the declared hosts.`);
        const isUrl = s.url === true;
        const header = s.header == null ? null : String(s.header);
        if (isUrl === (header != null)) problems.push(`${F}: secret ${name} needs exactly one of header (${POLICY.secretHeaders.join(", ")}) or url: true.`);
        else if (header != null && !POLICY.secretHeaders.includes(header)) problems.push(`${F}: secret ${name} header must be one of ${POLICY.secretHeaders.join(", ")}.`);
        secrets.push({ name, host: String(s.host || ""), ...(isUrl ? { url: true as const } : { header: header as string }), description: cleanText(s.description, 160) });
      }
    }
  }
  const ai = raw.ai === true;
  if (raw.ai != null && typeof raw.ai !== "boolean") problems.push(`${F}: ai must be true or false.`);
  if (!hosts.length && !ai && !problems.length) problems.push(`${F}: declares nothing (remove the file if the mod needs no network).`);
  if (problems.length) return { ok: false, problems: [...new Set(problems)], manifest: null };
  const body = { version: 1 as const, network: hosts.length ? { hosts, playerData, maxResponseKiB } : null, secrets, ai, policy: NET_POLICY_VERSION };
  return { ok: true, problems: [], manifest: { ...body, sha256: sha256Hex(canonical(body)) } };
}

