// Nxeon AI gateway: budget maths and states for AI features inside Cyrus mods. Pure and
// client-safe (no DB, no clock reads except through arguments).
//
// Owner rule (2026-10-08): networking must not burn tokens. Plain HTTP through the wrapper
// costs nothing; Cyrus tokens are only spent when a mod calls the Nxeon AI gateway, and then
// only inside hard limits:
//   1. AI in a mod is OFF until the server owner turns it on (per installed mod).
//   2. Daily budgets per mod and per server, set by the server owner, default 0 (nothing is
//      spent). Usage meter, warning at 80 %.
//   3. Hard stop at the budget. Every call reserves its WORST-CASE cost first (max input +
//      max output tokens); a call that might cross a budget is refused with "budget_reached",
//      and a settled call is never charged more than it reserved. No silent overspend.
//   4. Max output tokens per call and a per-minute call rate (per mod and per server).
//   5. A global platform daily cap and an admin kill switch.
//   6. Consent shows the budget and who pays (the server owner's Cyrus tokens).
//   7. Spend is exposed for the installed-mod row and the admin Cyrus overview (meter()).
// Design: /root/agent-notes/cyrus-v6/capabilities/AI-GATEWAY.md. Tests: test/cyrus-ai-gateway-budget.test.ts.

/** Platform-wide gateway settings (admin Settings, see SETTINGS_DEFAULTS `cyrus_ai_gw_*`). */
export type GatewayConfig = {
  /** `cyrus_ai_gateway_enabled`: the gateway exists at all (default false). */
  enabled: boolean;
  /** `cyrus_ai_gw_kill`: admin kill switch, wins over everything (default false). */
  killSwitch: boolean;
  /** `cyrus_ai_gw_platform_daily_cap`: Cyrus tokens per UTC day across every server (0 = nothing). */
  platformDailyCap: number;
  /** Hard ceiling on output tokens for one call, whatever the mod asks for. */
  maxOutputTokens: number;
  /** Longest prompt (characters) one call may send. */
  maxInputChars: number;
  callsPerMinutePerMod: number;
  callsPerMinutePerServer: number;
  /** Meter warns from this percentage. */
  warnPct: number;
  /** Economy conversion and the gateway model's list price (USD per million tokens). */
  tokensPerUsd: number;
  usdPerMInput: number;
  usdPerMOutput: number;
};

export const DEFAULT_GATEWAY_CONFIG: GatewayConfig = {
  enabled: false,
  killSwitch: false,
  platformDailyCap: 0,
  maxOutputTokens: 300,
  maxInputChars: 4000,
  callsPerMinutePerMod: 6,
  callsPerMinutePerServer: 20,
  warnPct: 80,
  tokensPerUsd: 500,
  usdPerMInput: 1,
  usdPerMOutput: 5,
};

/** Highest daily budget a server owner can set (Cyrus tokens), per mod or per server. */
export const MAX_DAILY_BUDGET = 100_000;

/** What the server owner sets for one installed mod (and their server). Defaults spend nothing. */
export type OwnerBudget = {
  /** The owner turned this mod's AI features on. */
  aiEnabled: boolean;
  /** Cyrus tokens per UTC day this mod may spend. */
  modDailyBudget: number;
  /** Cyrus tokens per UTC day all AI mods on this server may spend together. */
  serverDailyBudget: number;
};
export const DEFAULT_OWNER_BUDGET: OwnerBudget = { aiEnabled: false, modDailyBudget: 0, serverDailyBudget: 0 };

const clampInt = (n: unknown, lo: number, hi: number) => {
  const v = Math.floor(Number(n));
  return Number.isFinite(v) ? Math.min(hi, Math.max(lo, v)) : lo;
};

/** Sanitize what the owner typed (negative, fractional, huge or junk -> safe values). */
export function normalizeOwnerBudget(x: Partial<Record<keyof OwnerBudget, unknown>> | null | undefined): OwnerBudget {
  return {
    aiEnabled: x?.aiEnabled === true,
    modDailyBudget: clampInt(x?.modDailyBudget, 0, MAX_DAILY_BUDGET),
    serverDailyBudget: clampInt(x?.serverDailyBudget, 0, MAX_DAILY_BUDGET),
  };
}

/** Spend counters for the current UTC day, plus open reservations and the last minute's calls. */
export type GatewayUsage = {
  modSpent: number; modReserved: number;
  serverSpent: number; serverReserved: number;
  platformSpent: number; platformReserved: number;
  modCallsLastMinute: number; serverCallsLastMinute: number;
};
export const EMPTY_USAGE: GatewayUsage = { modSpent: 0, modReserved: 0, serverSpent: 0, serverReserved: 0, platformSpent: 0, platformReserved: 0, modCallsLastMinute: 0, serverCallsLastMinute: 0 };

/** Conservative token estimate for text (about 3 characters per token, rounded up). */
export const estimateInputTokens = (chars: number) => Math.ceil(Math.max(0, chars) / 3);

/** Cyrus tokens for a model usage, rounded UP so the platform never under-charges itself. */
export function cyrusTokensFor(inputTokens: number, outputTokens: number, cfg: GatewayConfig): number {
  const usd = (Math.max(0, inputTokens) * cfg.usdPerMInput + Math.max(0, outputTokens) * cfg.usdPerMOutput) / 1_000_000;
  return usd > 0 ? Math.max(1, Math.ceil(usd * cfg.tokensPerUsd - 1e-9)) : 0;
}

/** Worst-case cost of one call: the whole prompt plus the output ceiling. Reserved before the call. */
export function callReserve(promptChars: number, requestedMaxOutput: number | undefined, cfg: GatewayConfig): { reserve: number; maxOutputTokens: number } {
  const maxOutputTokens = clampInt(requestedMaxOutput ?? cfg.maxOutputTokens, 1, cfg.maxOutputTokens);
  return { reserve: cyrusTokensFor(estimateInputTokens(Math.min(promptChars, cfg.maxInputChars)), maxOutputTokens, cfg), maxOutputTokens };
}

export type DenyCode =
  | "gateway_killed" | "gateway_off" | "ai_not_enabled" | "no_budget" | "prompt_too_long"
  | "rate_limited" | "platform_cap" | "server_budget_reached" | "budget_reached";

export type CallDecision =
  | { ok: true; reserve: number; maxOutputTokens: number }
  | { ok: false; code: DenyCode; status: 403 | 413 | 429 | 503; message: string; retryAfterSec?: number };

const deny = (code: DenyCode, status: 403 | 413 | 429 | 503, message: string, retryAfterSec?: number): CallDecision => ({ ok: false, code, status, message, ...(retryAfterSec ? { retryAfterSec } : {}) });

/**
 * Decide one gateway call. Order matters: switches first, then the owner's opt-in, then rate,
 * then every budget against the call's worst case (spent + open reservations + this reserve).
 * `secondsToNextMinute` lets the caller say when a rate-limited mod may try again.
 */
export function decideCall(a: { cfg: GatewayConfig; budget: OwnerBudget; usage: GatewayUsage; promptChars: number; requestedMaxOutput?: number; secondsToNextMinute?: number; secondsToReset?: number }): CallDecision {
  const { cfg, usage } = a;
  const budget = normalizeOwnerBudget(a.budget);
  if (cfg.killSwitch) return deny("gateway_killed", 503, "Nxeon AI is paused for all mods right now.");
  if (!cfg.enabled) return deny("gateway_off", 503, "Nxeon AI for mods is not available yet.");
  if (!budget.aiEnabled) return deny("ai_not_enabled", 403, "The server owner has not turned on AI for this mod.");
  if (budget.modDailyBudget <= 0 || budget.serverDailyBudget <= 0) return deny("no_budget", 403, "The server owner has not set a daily AI budget for this mod.");
  if (a.promptChars > cfg.maxInputChars) return deny("prompt_too_long", 413, `The prompt is longer than ${cfg.maxInputChars} characters.`);
  const wait = a.secondsToNextMinute && a.secondsToNextMinute > 0 ? Math.ceil(a.secondsToNextMinute) : 60;
  if (usage.modCallsLastMinute >= cfg.callsPerMinutePerMod) return deny("rate_limited", 429, `This mod may make ${cfg.callsPerMinutePerMod} AI calls a minute.`, wait);
  if (usage.serverCallsLastMinute >= cfg.callsPerMinutePerServer) return deny("rate_limited", 429, `This server may make ${cfg.callsPerMinutePerServer} AI calls a minute.`, wait);
  const { reserve, maxOutputTokens } = callReserve(a.promptChars, a.requestedMaxOutput, cfg);
  const reset = a.secondsToReset && a.secondsToReset > 0 ? Math.ceil(a.secondsToReset) : undefined;
  if (usage.platformSpent + usage.platformReserved + reserve > cfg.platformDailyCap) return deny("platform_cap", 503, "Nxeon AI has reached today's platform limit. It resets at midnight UTC.", reset);
  if (usage.serverSpent + usage.serverReserved + reserve > budget.serverDailyBudget) return deny("server_budget_reached", 429, "This server's daily AI budget is reached. It resets at midnight UTC.", reset);
  if (usage.modSpent + usage.modReserved + reserve > budget.modDailyBudget) return deny("budget_reached", 429, "This mod's daily AI budget is reached. It resets at midnight UTC.", reset);
  return { ok: true, reserve, maxOutputTokens };
}

/**
 * Settle a finished call: charge the real cost, never more than was reserved (the reserve is
 * the hard ceiling the budgets were checked against). Failed calls with no model output are
 * charged only what the model really used (often 0).
 */
export function settleCall(reserve: number, inputTokens: number, outputTokens: number, cfg: GatewayConfig): { charge: number; released: number; capped: boolean } {
  const actual = cyrusTokensFor(inputTokens, outputTokens, cfg);
  const charge = Math.min(actual, Math.max(0, reserve));
  return { charge, released: Math.max(0, reserve - charge), capped: actual > reserve };
}

export type MeterState = "off" | "no-budget" | "ok" | "warn" | "reached";
export type Meter = { state: MeterState; used: number; budget: number; remaining: number; pct: number; label: string };

/** A usage meter for the installed-mod row, the owner's budget screen and the admin overview. */
export function meter(used: number, budget: number, opts: { aiEnabled?: boolean; warnPct?: number } = {}): Meter {
  const u = Math.max(0, Math.floor(used));
  const b = Math.max(0, Math.floor(budget));
  const warnPct = opts.warnPct ?? DEFAULT_GATEWAY_CONFIG.warnPct;
  if (opts.aiEnabled === false) return { state: "off", used: u, budget: b, remaining: 0, pct: 0, label: "AI off" };
  if (b === 0) return { state: "no-budget", used: u, budget: 0, remaining: 0, pct: 0, label: "No AI budget set (nothing is spent)" };
  const pct = Math.min(100, Math.floor((u / b) * 100));
  const remaining = Math.max(0, b - u);
  const state: MeterState = u >= b ? "reached" : pct >= warnPct ? "warn" : "ok";
  const label = state === "reached" ? `Daily AI budget reached (${u.toLocaleString("en-US")} of ${b.toLocaleString("en-US")} tokens)` : `${u.toLocaleString("en-US")} of ${b.toLocaleString("en-US")} tokens today${state === "warn" ? ` (${pct}%)` : ""}`;
  return { state, used: u, budget: b, remaining, pct, label };
}

/** UTC day key for the daily counters, and seconds until they reset. */
export function dayKey(now: Date): string { return now.toISOString().slice(0, 10); }
export function secondsToUtcMidnight(now: Date): number {
  const next = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1);
  return Math.max(1, Math.ceil((next - now.getTime()) / 1000));
}

/** Text for the consent screen (requirement 6). */
export function budgetConsentLines(b: OwnerBudget): string[] {
  const n = normalizeOwnerBudget(b);
  if (!n.aiEnabled || n.modDailyBudget === 0) return ["AI features stay off until you turn them on and set a daily budget. Nothing is spent until then.", "AI use is paid from your Cyrus tokens (the server owner's account)."];
  return [
    `This mod may spend up to ${n.modDailyBudget.toLocaleString("en-US")} Cyrus tokens a day on AI (your server: ${n.serverDailyBudget.toLocaleString("en-US")} a day for all mods).`,
    "AI use is paid from your Cyrus tokens (the server owner's account). At the limit the mod's AI stops until midnight UTC; it never goes over.",
  ];
}

