// Nxeon AI gateway for Cyrus mods: SERVER-ONLY stub (token check + settings + the budget
// decision). It never calls a model. With every default (gateway off, budgets 0) every request
// is refused. Design: /root/agent-notes/cyrus-v6/capabilities/AI-GATEWAY.md.
import { createHmac, timingSafeEqual } from "node:crypto";
import { getAllSettings, isTrue } from "../settings";
import { DEFAULT_GATEWAY_CONFIG, type GatewayConfig } from "./ai-gateway-budget";

const TOKEN_PREFIX = "nxai1";

function key(): Buffer {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET is not set");
  return createHmac("sha256", secret).update("cyrus-ai-gateway-v1").digest();
}
const b64u = (b: Buffer | string) => Buffer.from(b).toString("base64url");

export type GatewayTokenClaims = { serverId: string; modId: string; issuedAt: number };

/**
 * Per-server, per-mod token the Nxeon panel places on the customer's server (never in the
 * mod's jar or source). Stateless HMAC for the stub; the real gateway should store a hash so a
 * token can be revoked on its own (AI-GATEWAY.md "Tokens").
 */
export function issueGatewayToken(c: GatewayTokenClaims): string {
  const payload = b64u(JSON.stringify({ s: c.serverId, m: c.modId, iat: c.issuedAt }));
  const sig = b64u(createHmac("sha256", key()).update(`${TOKEN_PREFIX}.${payload}`).digest());
  return `${TOKEN_PREFIX}.${payload}.${sig}`;
}

export function verifyGatewayToken(token: string | null | undefined): GatewayTokenClaims | null {
  const parts = String(token || "").split(".");
  if (parts.length !== 3 || parts[0] !== TOKEN_PREFIX) return null;
  const want = createHmac("sha256", key()).update(`${parts[0]}.${parts[1]}`).digest();
  const got = Buffer.from(parts[2], "base64url");
  if (got.length !== want.length || !timingSafeEqual(got, want)) return null;
  try {
    const p = JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8")) as { s?: unknown; m?: unknown; iat?: unknown };
    if (typeof p.s !== "string" || typeof p.m !== "string" || typeof p.iat !== "number") return null;
    return { serverId: p.s, modId: p.m, issuedAt: p.iat };
  } catch { return null; }
}

/** Platform settings -> GatewayConfig (defaults: off, cap 0). */
export async function loadGatewayConfig(): Promise<GatewayConfig> {
  const s = await getAllSettings();
  const int = (k: string, d: number) => { const n = parseInt(s[k] ?? "", 10); return Number.isFinite(n) && n >= 0 ? n : d; };
  return {
    ...DEFAULT_GATEWAY_CONFIG,
    enabled: isTrue(s.cyrus_ai_gateway_enabled),
    killSwitch: isTrue(s.cyrus_ai_gw_kill),
    platformDailyCap: int("cyrus_ai_gw_platform_daily_cap", 0),
    maxOutputTokens: Math.max(1, Math.min(2000, int("cyrus_ai_gw_max_output_tokens", DEFAULT_GATEWAY_CONFIG.maxOutputTokens))),
    callsPerMinutePerMod: int("cyrus_ai_gw_calls_per_min_mod", DEFAULT_GATEWAY_CONFIG.callsPerMinutePerMod),
    callsPerMinutePerServer: int("cyrus_ai_gw_calls_per_min_server", DEFAULT_GATEWAY_CONFIG.callsPerMinutePerServer),
    tokensPerUsd: int("cyrus_tok_tokens_per_usd", DEFAULT_GATEWAY_CONFIG.tokensPerUsd) || DEFAULT_GATEWAY_CONFIG.tokensPerUsd,
  };
}

