// Nxeon AI gateway for Cyrus mods: STUB. Mods never talk to a model provider; the wrapper's
// NxAi helper calls this endpoint with the per-server token the Nxeon panel placed on the
// server. Today it validates and applies every limit, then answers 501: there is no model
// plumbing, no usage store and no charge. With the defaults (gateway off, budgets 0) every
// request is refused before anything else. Design: agent-notes/cyrus-v6/capabilities/AI-GATEWAY.md.
import { NextResponse } from "next/server";
import { checkRateLimit } from "@/lib/rate-limit";
import { loadGatewayConfig, verifyGatewayToken } from "@/lib/cyrus/ai-gateway";
import { DEFAULT_OWNER_BUDGET, EMPTY_USAGE, decideCall, secondsToUtcMidnight } from "@/lib/cyrus/ai-gateway-budget";

export const dynamic = "force-dynamic";

const json = (status: number, body: Record<string, unknown>, headers: Record<string, string> = {}) =>
  NextResponse.json(body, { status, headers: { "Cache-Control": "no-store", ...headers } });

export async function POST(req: Request) {
  const cfg = await loadGatewayConfig();
  if (cfg.killSwitch) return json(503, { error: "gateway_killed", message: "Nxeon AI is paused for all mods right now." });
  if (!cfg.enabled) return json(503, { error: "gateway_off", message: "Nxeon AI for mods is not available yet." });

  const auth = req.headers.get("authorization") || "";
  const claims = verifyGatewayToken(auth.startsWith("Bearer ") ? auth.slice(7) : "");
  if (!claims) return json(401, { error: "bad_token" });
  // Cheap in-memory flood guard in front of the real per-mod limits.
  const rl = checkRateLimit(`cyrus-ai-gw:${claims.serverId}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) return json(429, { error: "rate_limited" }, { "Retry-After": String(rl.retryAfterSec) });

  const raw = await req.text();
  if (raw.length > 16_000) return json(413, { error: "too_large" });
  let body: { prompt?: unknown; maxOutputTokens?: unknown };
  try { body = JSON.parse(raw || "{}"); } catch { return json(400, { error: "bad_json" }); }
  const prompt = typeof body.prompt === "string" ? body.prompt : "";
  if (!prompt.trim()) return json(400, { error: "prompt_required" });

  // Stub: no owner-budget or usage store yet, so the owner's settings are the defaults
  // (AI off, budget 0) and the call is refused with the reason the mod would really see.
  const now = new Date();
  const d = decideCall({
    cfg, budget: DEFAULT_OWNER_BUDGET, usage: EMPTY_USAGE, promptChars: prompt.length,
    requestedMaxOutput: typeof body.maxOutputTokens === "number" ? body.maxOutputTokens : undefined,
    secondsToNextMinute: 60 - now.getUTCSeconds(), secondsToReset: secondsToUtcMidnight(now),
  });
  if (!d.ok) return json(d.status, { error: d.code, message: d.message }, d.retryAfterSec ? { "Retry-After": String(d.retryAfterSec) } : {});
  return json(501, { error: "model_not_connected", message: "The Nxeon AI gateway is a stub. Nothing was charged." });
}
EOF
