"use client";

// What a Cyrus mod connects to, and the customer's explicit confirm before installing it.
//
// Contract for the install dialog (lifecycle agent) and any other install surface:
//   <CapabilityConsent capabilities={result.capabilities} aiBudget={ownerBudget} onChange={setAccepted} />
//   - capabilities: the build's `result.capabilities` (unknown is fine; it is re-validated here).
//     null/undefined -> renders nothing and calls onChange(NO_CAPABILITIES) once: nothing to confirm.
//   - onChange(sha256 | null): the manifest hash once the box is ticked, null while unticked.
//     Send it as `acceptCapabilities` in the install POST body; the route refuses a missing or
//     different hash (409 consent_required) and refuses every networking mod while
//     `cyrus_mod_networking_enabled` is off (403 networking_off).
//   - aiBudget: the owner's current AI budget for this mod (lib/cyrus/ai-gateway-budget.ts);
//     shown so the customer sees who pays and how much at most.
// <CapabilitySummary capabilities=... /> is the read-only card for the listing page, the Explain
// tab and NxLabs. Both use the Cyrus theme tokens (.cy-tokens) and fall back to neutral colours.
import { useEffect, useId, useState } from "react";
import { readCapabilities, summarizeCapabilities, type CapabilityRisk } from "@/lib/cyrus/capabilities";
import { budgetConsentLines, DEFAULT_OWNER_BUDGET, type OwnerBudget } from "@/lib/cyrus/ai-gateway-budget";

export const NO_CAPABILITIES = "none";

const RISK: Record<CapabilityRisk, { label: string; color: string }> = {
  none: { label: "Offline", color: "var(--cy-ok, #16a34a)" },
  low: { label: "Connects to the internet", color: "var(--cy-accent-ink, #6d28d9)" },
  medium: { label: "Connects and shares data", color: "var(--cy-warn, #b45309)" },
  high: { label: "Can send IP addresses", color: "var(--cy-bad, #be123c)" },
};

const box: React.CSSProperties = {
  border: "1px solid var(--cy-line2, rgba(100,100,140,.3))",
  background: "var(--cy-raise, rgba(100,100,140,.05))",
  borderRadius: "var(--cy-r-md, 11px)",
  padding: "12px 14px",
  color: "var(--cy-ink2, inherit)",
  fontSize: 13,
  lineHeight: 1.5,
  overflowWrap: "anywhere",
};

function Lines({ lines }: { lines: string[] }) {
  return (
    <ul style={{ margin: "8px 0 0", paddingLeft: 18, display: "grid", gap: 4 }}>
      {lines.map((l, i) => <li key={i}>{l}</li>)}
    </ul>
  );
}

function RiskChip({ risk }: { risk: CapabilityRisk }) {
  const r = RISK[risk];
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 11.5, fontWeight: 600, color: r.color }}>
      <span aria-hidden style={{ width: 7, height: 7, borderRadius: 99, background: r.color }} />
      {r.label}
    </span>
  );
}

/** Read-only: listing page, Explain tab, NxLabs page. */
export function CapabilitySummary({ capabilities, title = "Network access" }: { capabilities: unknown; title?: string }) {
  const m = readCapabilities({ capabilities });
  const s = summarizeCapabilities(m);
  return (
    <section style={box} aria-label={title}>
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 8, justifyContent: "space-between" }}>
        <strong style={{ color: "var(--cy-ink, inherit)", fontSize: 13 }}>{title}</strong>
        <RiskChip risk={s.risk} />
      </div>
      <Lines lines={capabilities != null && !m ? ["This mod's network permissions no longer meet Nxeon's rules. Rebuild it to use it."] : s.lines} />
    </section>
  );
}

/** Install-time consent. Renders nothing for an offline mod. */
export function CapabilityConsent({ capabilities, aiBudget = DEFAULT_OWNER_BUDGET, onChange, disabled }: {
  capabilities: unknown;
  aiBudget?: OwnerBudget;
  onChange: (acceptedSha256: string | null) => void;
  disabled?: boolean;
}) {
  const id = useId();
  const m = readCapabilities({ capabilities });
  const [checked, setChecked] = useState(false);
  const sha = m?.sha256 ?? null;
  // Offline mods need no consent; a changed manifest resets the tick.
  useEffect(() => { setChecked(false); onChange(capabilities == null ? NO_CAPABILITIES : null); }, [sha, capabilities == null]); // eslint-disable-line react-hooks/exhaustive-deps
  if (capabilities == null) return null;
  if (!m) return <div role="alert" style={{ ...box, borderColor: "var(--cy-alert-line, rgba(190,18,60,.4))" }}>This mod&apos;s network permissions no longer meet Nxeon&apos;s rules, so it can&apos;t be installed. Rebuild it to fix this.</div>;
  const s = summarizeCapabilities(m);
  const hosts = m.network?.hosts.map((h) => h.host) ?? [];
  return (
    <section style={box} aria-label="What this mod connects to">
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 8, justifyContent: "space-between" }}>
        <strong style={{ color: "var(--cy-ink, inherit)", fontSize: 13 }}>This mod connects to the internet</strong>
        <RiskChip risk={s.risk} />
      </div>
      <Lines lines={s.lines} />
      {m.ai && <Lines lines={budgetConsentLines(aiBudget)} />}
      <p style={{ margin: "8px 0 0", fontSize: 12, color: "var(--cy-ink3, inherit)" }}>
        Ordinary web calls are free. Every call is logged, limited, and only goes to the hosts above. You can switch a mod&apos;s network access off at any time in the Mods tab.
      </p>
      <label htmlFor={id} style={{ display: "flex", gap: 8, alignItems: "flex-start", marginTop: 10, cursor: disabled ? "default" : "pointer", color: "var(--cy-ink, inherit)" }}>
        <input id={id} type="checkbox" disabled={disabled} checked={checked} style={{ marginTop: 3, accentColor: "var(--cy-accent, #7c3aed)" }}
          onChange={(e) => { setChecked(e.target.checked); onChange(e.target.checked ? m.sha256 : null); }} />
        <span>I allow this mod to connect to {hosts.length ? hosts.join(", ") : "Nxeon AI"}{m.network?.playerData.length ? " and to send the player data listed above" : ""}.</span>
      </label>
    </section>
  );
}
