mkdir -p /tank/dev-worktrees/cyrus-v6-capabilities/services/modbuilder/nxnet/src/dev/nxeon/cyrus/net && cat > /tank/dev-worktrees/cyrus-v6-capabilities/services/modbuilder/nxnet/src/dev/nxeon/cyrus/net/NxHttp.java <<'EOF'
package dev.nxeon.cyrus.net;

// STUB of the Nxeon network wrapper for Cyrus mods (design: agent-notes/cyrus-v6/capabilities/DESIGN.md).
//
// This file fixes the PUBLIC API a generated plugin is allowed to call, and the allow-list rule.
// It has no transport: every call completes with Result.refused("not_available"). It is not
// compiled into the build image yet (the Dockerfile does not reference nxnet/), so nothing ships.
// The transport (HTTPS only, pinned resolved address, limits, logging, kill switches) is to be
// written and then reviewed by a human security reviewer before any build may include it
// (ROLLOUT.md, phase 1 gate).
//
// Usage a plugin will write:
//   NxHttp.of(this).get("https://api.example.com/v1/status")
//       .send(result -> { if (result.ok()) getLogger().info(result.body()); });
// Callbacks run on the server's main thread; there is no blocking method.

import java.util.Collections;
import java.util.Locale;
import java.util.Set;
import java.util.function.Consumer;

public final class NxHttp {
    private final String pluginName;
    private final Set<String> hosts;

    private NxHttp(String pluginName, Set<String> hosts) {
        this.pluginName = pluginName;
        this.hosts = Collections.unmodifiableSet(hosts);
    }

    /** One wrapper per plugin. Reads the build stamp (nx-capabilities.properties) from the plugin jar. */
    public static NxHttp of(org.bukkit.plugin.Plugin plugin) {
        return new NxHttp(plugin.getName(), Stamp.hosts(plugin));
    }

    public Request get(String url) { return new Request(this, "GET", url); }
    public Request post(String url) { return new Request(this, "POST", url); }

    /** Exact, case-insensitive match against the declared hosts. Checked before any lookup. */
    boolean declared(String host) {
        return host != null && hosts.contains(host.toLowerCase(Locale.ROOT));
    }

    public static final class Request {
        private final NxHttp owner;
        private final String method;
        private final String url;
        private String body = "";
        private String contentType = "application/json";

        private Request(NxHttp owner, String method, String url) {
            this.owner = owner; this.method = method; this.url = url;
        }

        public Request json(String json) { this.body = json == null ? "" : json; this.contentType = "application/json"; return this; }
        public Request form(String form) { this.body = form == null ? "" : form; this.contentType = "application/x-www-form-urlencoded"; return this; }

        /** Asynchronous; the callback always runs, on the main thread. */
        public void send(Consumer<Result> callback) {
            // Stub: no transport. The real wrapper validates url/host here first.
            callback.accept(Result.refused("not_available"));
        }
    }

    public static final class Result {
        private final int status;
        private final String body;
        private final String refusal;

        private Result(int status, String body, String refusal) { this.status = status; this.body = body; this.refusal = refusal; }
        static Result refused(String code) { return new Result(0, "", code); }

        public boolean ok() { return refusal == null && status >= 200 && status < 300; }
        public int status() { return status; }
        public String body() { return body; }
        /** Why the wrapper refused the call (not_declared, rate_limited, daily_bytes, disabled, ...), or null. */
        public String refusal() { return refusal; }
    }

    /** Reads the hosts line of the stamp the build service writes. */
    static final class Stamp {
        private Stamp() {}
        static Set<String> hosts(org.bukkit.plugin.Plugin plugin) {
            java.util.Properties p = new java.util.Properties();
            try (java.io.InputStream in = plugin.getResource("nx-capabilities.properties")) {
                if (in == null) return Collections.emptySet();
                p.load(in);
            } catch (java.io.IOException e) {
                return Collections.emptySet();
            }
            java.util.Set<String> out = new java.util.HashSet<>();
            for (String h : p.getProperty("hosts", "").split(",")) if (!h.isBlank()) out.add(h.trim().toLowerCase(Locale.ROOT));
            return out;
        }
    }
}
