        public String body() { return body; }
        /** Why the wrapper refused the call (not_declared, rate_limited, daily_bytes, disabled, ...), or null. */
        public String refusal() { return refusal; }
    }

    /** Reads the hosts line of the stamp the build service writes. */
    static final class Stamp {
        private Stamp() {}
        static Set<String> hosts(org.bukkit.plugin.Plugin plugin) {
            java.util.Properties p = new java.util.Properties();
            try (java.io.InputStream in = plugin.getResource("nx-capabilities.properties")) {
                if (in == null) return Collections.emptySet();
                p.load(in);
            } catch (java.io.IOException e) {
                return Collections.emptySet();
            }
            java.util.Set<String> out = new java.util.HashSet<>();
            for (String h : p.getProperty("hosts", "").split(",")) if (!h.isBlank()) out.add(h.trim().toLowerCase(Locale.ROOT));
            return out;
        }
    }
}
