    assert.equal(tail.trim(), createHash("sha256").update(body).digest("hex"));
  });
});

describe("install gate", () => {
  const w = validateCapabilities(weather);
  assert.ok(w.ok);
  it("offline mods install as before", () => {
    assert.deepEqual(capabilityGate({ capabilities: null, networkingEnabled: false }), { ok: true, manifest: null });
  });
  it("networking mods need the platform switch", () => {
    const g = capabilityGate({ capabilities: w.manifest, networkingEnabled: false, acceptedSha256: w.manifest.sha256 });
    assert.equal(g.ok, false); if (!g.ok) assert.equal(g.code, "networking_off");
  });
  it("and consent for exactly this manifest", () => {
    for (const acc of [null, "", "0".repeat(64)]) {
      const g = capabilityGate({ capabilities: w.manifest, networkingEnabled: true, acceptedSha256: acc });
      assert.equal(g.ok, false); if (!g.ok) assert.equal(g.code, "consent_required");
    }
    assert.equal(capabilityGate({ capabilities: w.manifest, networkingEnabled: true, acceptedSha256: w.manifest.sha256 }).ok, true);
  });
  it("a stored manifest that no longer meets the policy is refused", () => {
    const bad = { ...w.manifest, network: { ...w.manifest.network, hosts: [{ host: "x.nip.io", purpose: "Now on the deny list" }] } };
    const g = capabilityGate({ capabilities: bad, networkingEnabled: true, acceptedSha256: w.manifest.sha256 });
    assert.equal(g.ok, false); if (!g.ok) assert.equal(g.code, "manifest_invalid");
    assert.equal(readCapabilities({ capabilities: bad }), null);
  });
});

describe("free network limits", () => {
  const zero = { callsLastMinute: 0, bytesOutToday: 0, bytesInToday: 0 };
  it("allows ordinary use and stops nuisance traffic", () => {
    assert.deepEqual(checkNetLimits(zero, 200), { ok: true });
    assert.equal((checkNetLimits({ ...zero, callsLastMinute: NET_LIMITS.callsPerMinute }, 10) as { code: string }).code, "rate_limited");
    assert.equal((checkNetLimits({ ...zero, bytesOutToday: NET_LIMITS.dailyBytesOut - 5 }, 10) as { code: string }).code, "daily_bytes_out");
    assert.equal((checkNetLimits({ ...zero, bytesInToday: NET_LIMITS.dailyBytesIn }, 10) as { code: string }).code, "daily_bytes_in");
    assert.equal((checkNetLimits(zero, NET_LIMITS.maxRequestKiB * 1024 + 1) as { code: string }).code, "request_too_large");
  });
});
