cat > test/cyrus-ai-gateway-budget.test.ts <<'EOF'
// Nxeon AI gateway budget maths: off by default, owner-set daily budgets, hard stop, no overspend.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  DEFAULT_GATEWAY_CONFIG, DEFAULT_OWNER_BUDGET, EMPTY_USAGE, MAX_DAILY_BUDGET, budgetConsentLines, callReserve, cyrusTokensFor,
  dayKey, decideCall, meter, normalizeOwnerBudget, secondsToUtcMidnight, settleCall, type GatewayConfig,
} from "../lib/cyrus/ai-gateway-budget";

const cfg: GatewayConfig = { ...DEFAULT_GATEWAY_CONFIG, enabled: true, platformDailyCap: 1_000_000 };
const on = { aiEnabled: true, modDailyBudget: 100, serverDailyBudget: 300 };
const call = (o: Partial<Parameters<typeof decideCall>[0]> = {}) => decideCall({ cfg, budget: on, usage: EMPTY_USAGE, promptChars: 600, ...o });

describe("defaults spend nothing", () => {
  it("owner budget defaults: AI off, 0 and 0", () => {
    assert.deepEqual(DEFAULT_OWNER_BUDGET, { aiEnabled: false, modDailyBudget: 0, serverDailyBudget: 0 });
    assert.equal(DEFAULT_GATEWAY_CONFIG.enabled, false);
    assert.equal(DEFAULT_GATEWAY_CONFIG.platformDailyCap, 0);
  });
  it("every default refuses a call", () => {
    assert.equal((decideCall({ cfg: DEFAULT_GATEWAY_CONFIG, budget: on, usage: EMPTY_USAGE, promptChars: 10 }) as { code: string }).code, "gateway_off");
    assert.equal((call({ budget: DEFAULT_OWNER_BUDGET }) as { code: string }).code, "ai_not_enabled");
    assert.equal((call({ budget: { ...on, modDailyBudget: 0 } }) as { code: string }).code, "no_budget");
    assert.equal((call({ budget: { ...on, serverDailyBudget: 0 } }) as { code: string }).code, "no_budget");
    assert.equal((call({ cfg: { ...cfg, platformDailyCap: 0 } }) as { code: string }).code, "platform_cap");
  });
  it("the kill switch wins over everything", () => {
    assert.equal((call({ cfg: { ...cfg, killSwitch: true } }) as { code: string }).code, "gateway_killed");
  });
});

describe("normalizing what the owner typed", () => {
  it("clamps junk to safe values", () => {
    assert.deepEqual(normalizeOwnerBudget({ aiEnabled: "yes", modDailyBudget: -5, serverDailyBudget: "abc" }), DEFAULT_OWNER_BUDGET);
    assert.deepEqual(normalizeOwnerBudget({ aiEnabled: true, modDailyBudget: 12.9, serverDailyBudget: 1e12 }), { aiEnabled: true, modDailyBudget: 12, serverDailyBudget: MAX_DAILY_BUDGET });
    assert.deepEqual(normalizeOwnerBudget(null), DEFAULT_OWNER_BUDGET);
  });
});

describe("pricing and reservation", () => {
  it("rounds Cyrus tokens up, never charges for nothing", () => {
    assert.equal(cyrusTokensFor(0, 0, cfg), 0);
    assert.equal(cyrusTokensFor(1, 0, cfg), 1);
    // 1M in at $1 + 1M out at $5 = $6 = 3000 tokens at 500/USD
    assert.equal(cyrusTokensFor(1_000_000, 1_000_000, cfg), 3000);
  });
  it("reserves the worst case and caps output at the platform ceiling", () => {
    const r = callReserve(600, 10_000, cfg);
    assert.equal(r.maxOutputTokens, cfg.maxOutputTokens);
    assert.equal(r.reserve, cyrusTokensFor(200, cfg.maxOutputTokens, cfg));
    assert.equal(callReserve(600, 50, cfg).maxOutputTokens, 50);
    assert.equal(callReserve(600, 0, cfg).maxOutputTokens, 1);
  });
  it("refuses an over-long prompt", () => {
    assert.equal((call({ promptChars: cfg.maxInputChars + 1 }) as { code: string }).code, "prompt_too_long");
  });
});

describe("hard stop at the budget", () => {
  const { reserve } = callReserve(600, undefined, cfg);
  it("allows a call that fits", () => {
    const d = call();
    assert.ok(d.ok); if (d.ok) assert.equal(d.reserve, reserve);
  });
  it("refuses a call whose worst case would cross the mod budget, counting open reservations", () => {
    assert.ok(call({ usage: { ...EMPTY_USAGE, modSpent: 100 - reserve } }).ok);
    const d = call({ usage: { ...EMPTY_USAGE, modSpent: 100 - reserve, modReserved: 1 }, secondsToReset: 3600 });
    assert.equal(d.ok, false);
    if (!d.ok) { assert.equal(d.code, "budget_reached"); assert.equal(d.status, 429); assert.equal(d.retryAfterSec, 3600); assert.match(d.message, /budget is reached/); }
  });
  it("server budget and platform cap stop it too", () => {
    assert.equal((call({ usage: { ...EMPTY_USAGE, serverSpent: 300 } }) as { code: string }).code, "server_budget_reached");
    assert.equal((call({ cfg: { ...cfg, platformDailyCap: 10 }, usage: { ...EMPTY_USAGE, platformSpent: 10 } }) as { code: string }).code, "platform_cap");
  });
  it("settling never charges more than was reserved", () => {
    assert.deepEqual(settleCall(5, 0, 0, cfg), { charge: 0, released: 5, capped: false });
    const s = settleCall(2, 1_000_000, 1_000_000, cfg);
    assert.equal(s.charge, 2); assert.equal(s.capped, true);
    const ok = settleCall(reserve, 200, 100, cfg);
    assert.ok(ok.charge <= reserve); assert.equal(ok.charge + ok.released, reserve);
  });
  it("a whole day of calls never ends above the budget", () => {
    let spent = 0, calls = 0;
    for (let i = 0; i < 10_000; i++) {
      const d = call({ usage: { ...EMPTY_USAGE, modSpent: spent, serverSpent: spent } });
      if (!d.ok) break;
      spent += settleCall(d.reserve, 200 + (i % 7) * 50, 300, cfg).charge;
      calls++;
    }
    assert.ok(spent <= on.modDailyBudget, `spent ${spent}`);
    assert.ok(calls > 0);
  });
});

describe("rate limits", () => {
  it("per mod and per server, with a retry hint", () => {
    const d = call({ usage: { ...EMPTY_USAGE, modCallsLastMinute: cfg.callsPerMinutePerMod }, secondsToNextMinute: 12.2 });
    assert.equal(d.ok, false); if (!d.ok) { assert.equal(d.code, "rate_limited"); assert.equal(d.retryAfterSec, 13); }
    assert.equal((call({ usage: { ...EMPTY_USAGE, serverCallsLastMinute: cfg.callsPerMinutePerServer } }) as { code: string }).code, "rate_limited");
  });
});

describe("meter", () => {
  it("states: off, no budget, ok, warn at 80 %, reached", () => {
    assert.equal(meter(0, 100, { aiEnabled: false }).state, "off");
    assert.equal(meter(0, 0).state, "no-budget");
    assert.equal(meter(79, 100).state, "ok");
    const w = meter(80, 100);
    assert.equal(w.state, "warn"); assert.equal(w.pct, 80); assert.equal(w.remaining, 20);
    const r = meter(100, 100);
    assert.equal(r.state, "reached"); assert.equal(r.remaining, 0); assert.match(r.label, /reached/);
    assert.equal(meter(150, 100).pct, 100);
    assert.equal(meter(1234, 5000).label, "1,234 of 5,000 tokens today");
  });
});

describe("days and consent text", () => {
  it("UTC day key and reset", () => {
    const t = new Date("2026-10-08T23:59:30Z");
    assert.equal(dayKey(t), "2026-10-08");
    assert.equal(secondsToUtcMidnight(t), 30);
  });
  it("consent says who pays and the most it can spend", () => {
    assert.match(budgetConsentLines(DEFAULT_OWNER_BUDGET).join(" "), /Nothing is spent/);
    const l = budgetConsentLines({ aiEnabled: true, modDailyBudget: 250, serverDailyBudget: 1000 }).join(" ");
    assert.match(l, /up to 250 Cyrus tokens a day/);
    assert.match(l, /server owner's account/);
    assert.match(l, /never goes over/);
  });
});
